-- Rattachement des nouvelles solutions aux indicateurs existants
update public.biblio_indicateurs set solution_noms='["Jardin permaculture","Repair café","Compostage partagé","Atelier de transmission"]'::jsonb, updated_at=now() where id='soc_formation';
update public.biblio_indicateurs set solution_noms='["Isolation paille","Potager en buttes","Haie champêtre","Mare écologique","Désimperméabilisation des sols","Chantier participatif"]'::jsonb, updated_at=now() where id='soc_benevoles';
